package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforcePayTemplatePublicationController;
import com.rpb.reservation.workforce.payroll.governance.*;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.walkin.auth.LocalRuntimeSecurityConfiguration;
import java.util.*;import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@WebMvcTest(WorkforcePayTemplatePublicationController.class)
@Import({LocalRuntimeSecurityConfiguration.class,com.rpb.reservation.appgate.api.AppGateApiErrorMapper.class})
@ActiveProfiles("local") @TestPropertySource(properties="rpb.local-auth.enabled=true")
class WorkforcePayTemplatePublicationLocalRuntimeSecurityTest {
 @Autowired MockMvc mvc;@MockBean CurrentActorProvider actors;@MockBean TemplatePublicationService publications;@MockBean TemplateAdoptionService adoptions;
 @MockBean com.rpb.reservation.appgate.application.AppGateService gate;@MockBean com.rpb.reservation.appgate.application.AppGateDenialAuditService denialAudit;
 @Test void onlyExactMethodsAndPathsReachTheAuthorizationLayer()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce";UUID id=UUID.randomUUID();for(var path:List.of("/pay-template-publication-directory","/pay-template-masters","/pay-template-library","/pay-template-library/"+id+"/preview?releaseVersion=1"))mvc.perform(get(base+path)).andExpect(status().isOk());for(var path:List.of("/pay-template-masters/"+id,"/pay-template-masters/"+id+"/publish","/pay-template-library/"+id+"/enable"))mvc.perform(put(base+path).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk());verify(publications).publish(any(),any(),eq(id),any());verify(adoptions).enable(any(),any(),eq(id),any());for(var path:List.of("/pay-template-publication-directory/private","/pay-template-library/private","/pay-template-library/"+id+"/preview/private","/pay-template-masters/"+id+"/private"))mvc.perform(get(base+path)).andExpect(status().isForbidden());mvc.perform(post(base+"/pay-template-library/"+id+"/enable")).andExpect(status().isForbidden());mvc.perform(delete(base+"/pay-template-masters/"+id)).andExpect(status().isForbidden());}
}
